import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z][a-zA-Z0-9_]{0,63}$");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportType = req.getParameter("report_type");
        String dateFrom = req.getParameter("date_from");
        String dateTo = req.getParameter("date_to");
        String sortColumn = req.getParameter("sort_by");
        String filterExpr = req.getParameter("filter");

        // Validate report type against whitelist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation
        if (!isValidDate(dateFrom) || !isValidDate(dateTo)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column validation - looks secure but sortColumn isn't used in injection
        if (sortColumn != null && !SAFE_IDENTIFIER.matcher(sortColumn).matches()) {
            sortColumn = "created_at";
        }

        // The filter parameter is used to build a dynamic WHERE clause
        // Developer assumed the ORM layer would handle escaping
        String query = buildReportQuery(reportType, dateFrom, dateTo, sortColumn, filterExpr);

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write(resultSetToJson(rs));

        } catch (SQLException e) {
            log("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String reportType, String dateFrom, 
                                     String dateTo, String sortColumn, String filterExpr) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM reports_").append(reportType);
        sb.append(" WHERE created_at BETWEEN '").append(dateFrom).append("' AND '").append(dateTo).append("'");

        // filterExpr is directly interpolated - SQL injection vulnerability
        if (filterExpr != null && !filterExpr.isEmpty()) {
            sb.append(" AND (").append(filterExpr).append(")");
        }

        sb.append(" ORDER BY ").append(sortColumn);
        sb.append(" LIMIT 1000");

        return sb.toString();
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory") || 
               type.equals("customers") || type.equals("returns"));
    }

    private boolean isValidDate(String date) {
        return date != null && date.matches("^\\d{4}-\\d{2}-\\d{2}$");
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder json = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) json.append(",");
            json.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) json.append(",");
                json.append("\"").append(meta.getColumnName(i)).append("\":");
                json.append("\"").append(rs.getString(i)).append("\"");
            }
            json.append("}");
            first = false;
        }
        json.append("]");
        return json.toString();
    }
}
